window.RI2_UNITS = {"8":{"unit":8,"code":"RI2-U08","title":"GREAT EXPLORERS","startNumber":186,"endNumber":217,"entries":[{"number":186,"term":"objective ~ goal","sourceTerm":"objective (n) ~ goal (n)","spoken":"objective , goal","ipa":"objective /əˈbdʒɛktɪv/ · goal /ɡoʊl/","type":"noun · noun","meaning":"mục tiêu","definition":"A result that a person or organization intends to achieve.","note":"objective thường cụ thể và trang trọng hơn goal; achieve/meet an objective.","example":"The expedition's main objective was to map the unexplored coast."},{"number":187,"term":"informal >< formal","sourceTerm":"informal >< formal","spoken":"informal , formal","ipa":"informal /ˌɪˈnfɔːrməl/ · formal /ˈfɔːrməl/","type":"adjective · adjective","meaning":"không trang trọng, thân mật · trang trọng, chính thức","definition":"Informal language or behaviour is relaxed and unofficial; formal language or behaviour follows accepted rules.","note":"","example":"The explorer used an informal tone in her diary but a formal style in the final report."},{"number":188,"term":"undertake","sourceTerm":"undertake (v)","spoken":"undertake","ipa":"undertake /ˈʌndɚˌteɪk/","type":"verb","meaning":"đảm nhận, tiến hành","definition":"To accept responsibility for and begin a difficult task or project.","note":"undertake a task/project/study; undertake to V trang trọng mang nghĩa cam kết làm gì.","example":"The research team undertook a two-year survey of the river."},{"number":189,"term":"journal · journalist · journalism","sourceTerm":"journal · journalist · journalism","spoken":"journal , journalist , journalism","ipa":"journal /ˈdʒɝːnəl/ · journalist /ˈdʒɝːnələst/ · journalism /ˈdʒɝːnəˌlɪzəm/","type":"noun · noun · noun","meaning":"tạp chí chuyên ngành; nhật ký · nhà báo · ngành báo chí","definition":"A journal is a personal record or academic publication; a journalist reports news, and journalism is that profession.","note":"journal có thể là nhật ký hoặc tạp chí chuyên ngành; journalist/journalism thuộc lĩnh vực báo chí.","example":"A journalist used the explorer's journal as a source for an article about early journalism."},{"number":190,"term":"admire · admiration","sourceTerm":"admire · admiration","spoken":"admire , admiration","ipa":"admire /æˈdmaɪr/ · admiration /ˌædmɚˈeɪʃən/","type":"verb · noun","meaning":"ngưỡng mộ · sự ngưỡng mộ","definition":"To admire is to respect or approve of someone greatly; admiration is that feeling.","note":"admire someone for + phẩm chất/hành động; have admiration for + người.","example":"Young scientists admire the explorer's courage and speak of her with admiration."},{"number":191,"term":"perceive · perception","sourceTerm":"perceive · perception","spoken":"perceive , perception","ipa":"perceive /pɚˈsiːv/ · perception /pɚˈsɛpʃən/","type":"verb · noun","meaning":"nhận thấy, nhìn nhận · nhận thức; cách nhìn","definition":"To perceive is to notice or understand something in a particular way; perception is that understanding or impression.","note":"perceive A as B; perception of + người/sự việc.","example":"Local people perceived the expedition as helpful, and their positive perception encouraged cooperation."},{"number":192,"term":"statue # status","sourceTerm":"statue # status","spoken":"statue , status","ipa":"statue /ˈstæˌtʃuː/ · status /ˈstætəs/","type":"noun · noun","meaning":"bức tượng · địa vị; trạng thái","definition":"A statue is a three-dimensional figure made from a hard material; status is a person's or thing's position or condition.","note":"statue # status: bức tượng # địa vị/trạng thái.","example":"The city built a statue after the explorer achieved national status."},{"number":193,"term":"administer · administrator · administration","sourceTerm":"administer · administrator · administration","spoken":"administer , administrator , administration","ipa":"administer /əˈdmɪnəstɚ/ · administrator /əˈdmɪnəˌstreɪtɚ/ · administration /æˌdmɪnɪˈstreɪʃən/","type":"verb · noun · noun","meaning":"quản trị, điều hành · người quản trị · sự hoặc bộ máy quản trị","definition":"To administer is to manage an organization or system; an administrator does this work, and administration is the process or group responsible.","note":"administer a program/organization; administer còn có nghĩa “cấp thuốc/tiến hành bài kiểm tra”.","example":"An experienced administrator was chosen to administer the project and improve its administration."},{"number":194,"term":"mineral","sourceTerm":"mineral (n)","spoken":"mineral","ipa":"mineral /ˈmɪnɚəl/","type":"noun","meaning":"khoáng chất","definition":"A natural solid substance found in rocks and the earth.","note":"","example":"The explorers collected mineral samples from the mountain."},{"number":195,"term":"plentiful ~ abundant · plenty of","sourceTerm":"plentiful ~ abundant · plenty of","spoken":"plentiful , abundant , plenty of","ipa":"plentiful /ˈplɛntəfəl/ · abundant /əˈbʌndənt/ · plenty /ˈplɛnti/","type":"adjective · adjective","meaning":"dồi dào, phong phú · rất nhiều, dư dả","definition":"Plentiful and abundant mean available in large amounts; plenty of means more than enough.","note":"plentiful/abundant là tính từ; plenty of + danh từ. Abundant trang trọng hơn plentiful.","example":"Fresh water was plentiful near the river, and the forest provided plenty of food."},{"number":196,"term":"permit ~ allow · permission # allowance","sourceTerm":"permit ~ allow · permission # allowance","spoken":"permit , allow , permission , allowance","ipa":"permit /pɚˈmɪt/ · allow /əˈlaʊ/ · permission /pɚˈmɪʃən/ · allowance /əˈlaʊəns/","type":"verb · noun · noun","meaning":"cho phép · sự cho phép · tiền trợ cấp; khoản hoặc mức được cấp","definition":"To permit or allow is to let something happen; permission is approval, while an allowance is money or an amount provided regularly.","note":"permit/allow someone to V; permission to V; allowance không đồng nghĩa với permission trong nghĩa “tiền trợ cấp”.","example":"Officials permitted the survey after giving written permission and a travel allowance."},{"number":197,"term":"observe · observation · observant · observable · observatory","sourceTerm":"observe · observation · observant · observable · observatory","spoken":"observe , observation , observant , observable , observatory","ipa":"observe /əˈbzɝːv/ · observation /ˌɑːbzɚˈveɪʃən/ · observant /əˈbzɝːvənt/ · observable /əˈbzɝːvəbəl/ · observatory /əˈbzɝːvəˌtɔːri/","type":"verb · noun · noun · adjective · adjective","meaning":"quan sát · sự quan sát; nhận xét · tinh ý, giỏi quan sát · có thể quan sát được · đài quan sát","definition":"To observe is to watch carefully; an observation records what is noticed, an observant person notices details, observable means able to be seen, and an observatory is a place for studying the sky.","note":"observe + danh từ; make an observation; observant mô tả người tinh ý, còn observable nghĩa là có thể quan sát được.","example":"An observant researcher recorded each observable change as an observation at the mountain observatory."},{"number":198,"term":"voyage ~ journey","sourceTerm":"voyage ~ journey","spoken":"voyage , journey","ipa":"voyage /ˈvɔɪədʒ/ · journey /ˈdʒɝːni/","type":"noun · noun","meaning":"hành trình dài bằng đường biển hoặc trong không gian ~ hành trình, chuyến đi nói chung","definition":"A voyage is a long journey by sea or through space; journey is the broader word for travel from one place to another.","note":"go on/make a voyage; journey dùng rộng hơn cho mọi loại hành trình.","example":"The explorers began their journey by land before starting a six-month sea voyage."},{"number":199,"term":"intend to do · intention · be intent on something · intentional","sourceTerm":"intend to do · intention · be intent on something · intentional","spoken":"intend to do , intention , be intent on something , intentional","ipa":"intend /ˌɪˈntɛnd/ · intention /ˌɪˈntɛntʃən/ · intent /ˌɪˈntɛnt/ · something /ˈsʌmθɪŋ/ · intentional /ˌɪˈntɛnʃənəl/","type":"verb · noun · adjective · adjective · phrase / pattern","meaning":"dự định làm gì · ý định · quyết tâm làm gì · có chủ ý, cố ý","definition":"To intend is to plan; an intention is a plan, being intent on something means being determined, and intentional means done deliberately.","note":"intend to V; have no intention of V-ing; be intent on + danh từ/V-ing; intentional mang nghĩa cố ý.","example":"She intended to continue the voyage, was intent on reaching the island, and made an intentional change to the route."},{"number":200,"term":"abandon","sourceTerm":"abandon (v)","spoken":"abandon","ipa":"abandon /əˈbændən/","type":"verb","meaning":"bỏ mặc, bỏ rơi","definition":"To leave a person, place, or plan completely, especially in a difficult situation.","note":"abandon a plan/search/vehicle; thường hàm ý rời bỏ hoàn toàn và không quay lại.","example":"The crew had to abandon the damaged ship during the storm."},{"number":201,"term":"regard A as B","sourceTerm":"regard (v) A as B","spoken":"regard A as B","ipa":"regard /rɪˈɡɑːrd/ · as /æz/","type":"verb","meaning":"coi A là B","definition":"To consider or describe a person or thing in a particular way.","note":"regard A as B; không dùng regard A to be B trong mẫu thông dụng này.","example":"Historians regard the voyage as a major scientific achievement."},{"number":202,"term":"prior to · priority · prioritize","sourceTerm":"prior to · priority · prioritize","spoken":"prior to , priority , prioritize","ipa":"prior /ˈpraɪɚ/ · priority /praɪˈɔːrəti/ · prioritize /praɪˈɔːrəˌtaɪz/","type":"verb · noun · adjective · phrase / pattern","meaning":"trước (cách nói trang trọng) · điều hoặc sự ưu tiên · ưu tiên, xếp thứ tự ưu tiên","definition":"Prior to means before; a priority is something more important than other matters, and to prioritize is to treat it as more important.","note":"prior to + danh từ/V-ing là cấu trúc trang trọng; give priority to + danh từ.","example":"Prior to departure, the team prioritized safety and made clean water its first priority."},{"number":203,"term":"soldier","sourceTerm":"soldier (n)","spoken":"soldier","ipa":"soldier /ˈsoʊldʒɚ/","type":"noun","meaning":"lính, binh lính","definition":"A member of an army, especially one who is not an officer.","note":"","example":"A former soldier guided the expedition through the mountain pass."},{"number":204,"term":"finance · financial","sourceTerm":"finance · financial","spoken":"finance , financial","ipa":"finance /fəˈnæns/ · financial /fəˈnænʃəl/","type":"noun · adjective","meaning":"tài chính; việc quản lí tiền · thuộc về tài chính","definition":"Finance concerns the management of money; financial describes matters related to money.","note":"finance có thể là danh từ hoặc động từ; financial + problem/support/market.","example":"Private finance supported the voyage when the team faced financial difficulties."},{"number":205,"term":"consent ~ agree","sourceTerm":"consent (v) ~ agree (v)","spoken":"consent , agree","ipa":"consent /kəˈnsɛnt/ · agree /əˈɡriː/","type":"verb · verb","meaning":"đồng ý, chấp thuận","definition":"To give permission or accept a proposal or request.","note":"consent to + danh từ/V-ing trang trọng; agree with + người/ý kiến, agree to + kế hoạch/đề nghị.","example":"Local leaders consented to the survey after residents agreed with its purpose."},{"number":206,"term":"wise · wisdom","sourceTerm":"wise · wisdom","spoken":"wise , wisdom","ipa":"wise /waɪz/ · wisdom /ˈwɪzdəm/","type":"noun · adjective","meaning":"khôn ngoan, sáng suốt · sự khôn ngoan, trí tuệ","definition":"Wise means able to make good decisions from knowledge and experience; wisdom is that ability.","note":"a wise decision/person; wisdom thường là danh từ không đếm được.","example":"It was wise to seek local advice, and the guide's wisdom prevented a dangerous mistake."},{"number":207,"term":"drown # sink","sourceTerm":"drown # sink","spoken":"drown , sink","ipa":"drown /draʊn/ · sink /sɪŋk/","type":"verb · verb","meaning":"chết đuối; làm chết đuối · chìm; làm chìm vật hoặc phương tiện","definition":"To drown is to die or cause a living thing to die under water; to sink is to move or cause an object to move below the water's surface.","note":"drown: chết/làm chết đuối; sink: chìm/làm chìm đồ vật hoặc phương tiện.","example":"The sailors wore safety equipment so that they would not drown if the boat sank."},{"number":208,"term":"scatter","sourceTerm":"scatter (v)","spoken":"scatter","ipa":"scatter /ˈskætɚ/","type":"verb","meaning":"rải rác, phân tán","definition":"To spread in different directions or over a wide area.","note":"scatter something across/over/around + nơi; be scattered across mang nghĩa nằm rải rác.","example":"The storm scattered the boats along the coast."},{"number":209,"term":"log · logging","sourceTerm":"log · logging","spoken":"log , logging","ipa":"log /lɔːɡ/ · logging /ˈlɔːɡɪŋ/","type":"verb · noun · noun","meaning":"khúc gỗ; bản ghi; ghi lại · hoạt động khai thác gỗ","definition":"A log is a thick piece of wood or a written record; to log is to record information, while logging is the activity of cutting trees.","note":"keep a log: ghi nhật trình; log data/hours: ghi lại dữ liệu/số giờ; logging: khai thác gỗ.","example":"The explorer logged the location of each fallen log in her field record."},{"number":210,"term":"broad · broaden","sourceTerm":"broad · broaden","spoken":"broad , broaden","ipa":"broad /brɔːd/ · broaden /ˈbrɔːdən/","type":"verb · adjective","meaning":"rộng, bao quát · mở rộng, làm phong phú thêm","definition":"Broad means wide or covering many subjects; to broaden is to make or become wider in range.","note":"broad range/view/knowledge; broaden someone's experience/understanding.","example":"The expedition had a broad research aim and helped broaden scientific knowledge of the region."},{"number":211,"term":"urge · urgent","sourceTerm":"urge · urgent","spoken":"urge , urgent","ipa":"urge /ɝːdʒ/ · urgent /ˈɝːdʒənt/","type":"verb · noun · adjective","meaning":"thúc giục; sự thôi thúc · khẩn cấp, cấp bách","definition":"To urge is to strongly encourage; an urge is a strong desire, while urgent means needing immediate attention.","note":"urge someone to V; have an urge to V; urgent: tính từ; urge: động từ/danh từ.","example":"Officials urged the team to return because an urgent storm warning had been issued."},{"number":212,"term":"mission","sourceTerm":"mission (n)","spoken":"mission","ipa":"mission /ˈmɪʃən/","type":"noun","meaning":"nhiệm vụ, sứ mệnh","definition":"An important task or journey with a clear purpose.","note":"go on/carry out/complete a mission.","example":"The rescue mission brought food and medicine to the isolated team."},{"number":213,"term":"slave · slavery","sourceTerm":"slave · slavery","spoken":"slave , slavery","ipa":"slave /sleɪv/ · slavery /ˈsleɪvɚi/","type":"noun · noun","meaning":"người bị bắt làm nô lệ · chế độ nô lệ","definition":"A slave is a person forced to work without freedom; slavery is the system that permits this.","note":"Trong văn viết hiện đại, enslaved person thường được ưu tiên khi nói về con người cụ thể.","example":"The historical study explains how trade supported slavery and harmed enslaved people."},{"number":214,"term":"empire","sourceTerm":"empire (n)","spoken":"empire","ipa":"empire /ˈɛmpaɪɚ/","type":"noun","meaning":"đế chế","definition":"A group of countries or territories ruled by one powerful state or leader.","note":"","example":"The map shows how the empire expanded through trade and military power."},{"number":215,"term":"numerous # various","sourceTerm":"numerous # various","spoken":"numerous , various","ipa":"numerous /ˈnuːmɚəs/ · various /ˈvɛriəs/","type":"adjective · adjective","meaning":"nhiều về số lượng · nhiều loại, đa dạng","definition":"Numerous means many in number; various means several different types or examples.","note":"numerous nhấn mạnh số lượng lớn; various nhấn mạnh sự đa dạng, nên không hoàn toàn đồng nghĩa.","example":"The explorer visited numerous islands and recorded various local traditions."},{"number":216,"term":"casual ~ informal >< formal","sourceTerm":"casual ~ informal >< formal","spoken":"casual , informal , formal","ipa":"casual /ˈkæʒəwəl/ · informal /ˌɪˈnfɔːrməl/ · formal /ˈfɔːrməl/","type":"adjective · adjective · adjective","meaning":"thường ngày, không trang trọng · trang trọng, chính thức","definition":"Casual and informal describe relaxed, unofficial styles; casual can also mean not regular, while formal follows official conventions.","note":"casual clothes/conversation/work; informal gần nghĩa nhưng casual còn có thể mang nghĩa “không thường xuyên”.","example":"The guide used informal language and casual clothes at camp but a formal style at the official ceremony."},{"number":217,"term":"drive · driver","sourceTerm":"drive · driver","spoken":"drive , driver","ipa":"drive /draɪv/ · driver /ˈdraɪvɚ/","type":"verb · noun","meaning":"thúc đẩy · người hoặc yếu tố thúc đẩy","definition":"To drive a change is to cause or strongly motivate it; a driver is the person or factor that causes progress.","note":"drive change/growth/demand; driver trong văn học thuật có thể là “yếu tố thúc đẩy”, không chỉ “tài xế”.","example":"Scientific curiosity drove the expedition, while trade was another major driver of exploration."}],"pronunciationFocus":[{"entryNumber":190,"points":[{"category":"word-stress","note":"admire nhấn âm tiết thứ hai; admiration chuyển trọng âm sang âm tiết chứa /eɪ/"}]},{"entryNumber":191,"points":[{"category":"common-error","note":"perceive có /iː/; perception đổi sang /ɛ/ và có phần cuối /pʃən/"},{"category":"final-sound","note":"perceive kết thúc bằng /v/"}]},{"entryNumber":193,"points":[{"category":"word-stress","note":"administer nhấn âm tiết thứ hai; administration chuyển trọng âm sang âm tiết chứa /streɪ/"}]},{"entryNumber":197,"points":[{"category":"word-stress","note":"observe nhấn âm tiết thứ hai; observation chuyển trọng âm sang âm tiết chứa /veɪ/"},{"category":"final-sound","note":"observe kết thúc bằng /v/"}]},{"entryNumber":201,"points":[{"category":"linking","note":"Đọc liền regard‿as, nối /d/ cuối regard sang nguyên âm /æ/ của as"}]},{"entryNumber":202,"points":[{"category":"word-stress","note":"prior nhấn âm đầu; priority và prioritize nhấn âm tiết thứ hai"}]},{"entryNumber":207,"points":[{"category":"final-sound","note":"drown kết thúc bằng /n/; sink kết thúc bằng cụm /ŋk/"}]}]}};
